'use client';

import { toSubmitError } from '@athene-x/whimui/form';
import { useTranslations } from 'next-intl';

import { Alert, AlertDescription } from '@/components/ui/alert';
import { cn } from '@/lib/utils';

export type LoadErrorProps = {
  error: unknown;
  className?: string;
};

/** The message of a failed query, in place of the content it would have shown. */
export function LoadError({ error, className }: LoadErrorProps) {
  const t = useTranslations('ui');

  return (
    <Alert variant="destructive" className={cn('max-w-xl', className)}>
      <AlertDescription>{toSubmitError(error, t('errors.loadFailed')).message}</AlertDescription>
    </Alert>
  );
}

import { useTranslations } from 'next-intl';

import { cn } from '@/lib/utils';

export function LoadingText({ className }: { className?: string }) {
  const t = useTranslations('ui');

  return (
    <p role="status" className={cn('text-sm text-muted-foreground', className)}>
      {t('status.loading')}
    </p>
  );
}

import { useTranslations } from 'next-intl';

import { Spinner } from '@/components/ui/spinner';

/** Full-area spinner for a route's `loading.tsx`. */
export function LoadingPage() {
  const t = useTranslations('ui');

  return (
    <div role="status" className="flex flex-1 items-center justify-center gap-2 p-12">
      <Spinner />
      <span className="text-sm text-muted-foreground">{t('status.loading')}</span>
    </div>
  );
}

import { Alert, AlertDescription } from '@/components/ui/alert';

/** The red banner above a form's footer; renders nothing without a message. */
export function ErrorAlert({ message }: { message: string | undefined }) {
  if (!message) return null;

  return (
    <Alert variant="destructive">
      <AlertDescription>{message}</AlertDescription>
    </Alert>
  );
}
